package com.example.onlinevoting;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.util.Base64;import android.widget.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import javax.crypto.Cipher;import android.security.keystore.*;import android.hardware.biometrics.BiometricPrompt;import android.os.CancellationSignal;

public class MainActivity extends Activity {
 EditText email,password; TextView status; String mode="login", baseUrl="http://10.0.2.2/online_voting_fixed"; String alias;
 @Override public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,60,40,40);TextView t=new TextView(this);t.setText("👆 ONLINE FINGER VOTING\n\nFingerprint Must Be Required");t.setTextSize(24);l.addView(t);email=new EditText(this);email.setHint("Voter email");l.addView(email);password=new EditText(this);password.setHint("Password (required for enrollment)");password.setInputType(129);l.addView(password);Button v=new Button(this);v.setText("VERIFY FINGERPRINT");l.addView(v);status=new TextView(this);l.addView(status);setContentView(l);handleIntent(getIntent());v.setOnClickListener(x->startFlow());}
 void handleIntent(Intent i){Uri u=i.getData();if(u!=null){String p=u.getPath();if(p!=null&&!p.equals("/"))mode=p.replace("/","");String e=u.getQueryParameter("email");if(e!=null)email.setText(e);}}
 void startFlow(){String e=email.getText().toString().trim();if(e.isEmpty()){status.setText("Enter email first.");return;}alias="voter_"+Integer.toHexString(e.hashCode());new Thread(()->{try{if(mode.equals("enroll")){generateKey();}else if(!hasKey())throw new Exception("Fingerprint is not enrolled. Register/enroll first.");String ch=extract(post("/biometric_challenge.php","email="+enc(e)+"&mode="+enc(mode)+"&password="+enc(password.getText().toString())),"challenge");if(ch==null)throw new Exception("Could not create biometric challenge.");runOnUiThread(()->authenticate(e,ch));}catch(Exception ex){runOnUiThread(()->status.setText(ex.getMessage()));}}).start();}
 void authenticate(String emailValue,String challenge){try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);PrivateKey pk=(PrivateKey)ks.getKey(alias,null);Signature sig=Signature.getInstance("SHA256withRSA");sig.initSign(pk);BiometricPrompt.CryptoObject crypto=new BiometricPrompt.CryptoObject(sig);new BiometricPrompt.Builder(this).setTitle("Fingerprint Required").setSubtitle("Use your enrolled fingerprint").setDescription("Fingerprint is mandatory to continue. Without it you cannot vote.").build().authenticate(crypto,new CancellationSignal(),getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){try{Signature s=r.getCryptoObject().getSignature();s.update(hexToBytes(challenge));String signature=Base64.encodeToString(s.sign(),Base64.NO_WRAP);String pub=Base64.encodeToString(pk.getPublic().getEncoded(),Base64.NO_WRAP);new Thread(()->finish(emailValue,challenge,signature,pub)).start();}catch(Exception e){status.setText(e.getMessage());}}@Override public void onAuthenticationFailed(){status.setText("Fingerprint not recognized. Try again.");}@Override public void onAuthenticationError(int c,CharSequence s){status.setText("Biometric error: "+s);}});}catch(Exception e){status.setText(e.getMessage());}}
 void finish(String e,String ch,String sig,String pub){try{String res=post("/biometric_verify.php","email="+enc(e)+"&mode="+enc(mode)+"&challenge="+enc(ch)+"&signature="+enc(sig)+"&public_key="+enc(pub));String token=extract(res,"token");if(token==null)throw new Exception(res);startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(baseUrl+"/biometric_login.php?token="+token)));}catch(Exception ex){runOnUiThread(()->status.setText(ex.getMessage()));}}
 void generateKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(alias))return;KeyPairGenerator g=KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA,"AndroidKeyStore");g.initialize(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_SIGN).setDigests(KeyProperties.DIGEST_SHA256).setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1).setUserAuthenticationRequired(true).setUserAuthenticationValidityDurationSeconds(-1).build());g.generateKeyPair();}
 boolean hasKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);return ks.containsAlias(alias);}
 String post(String path,String data)throws Exception{URL u=new URL(baseUrl+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(data.getBytes(StandardCharsets.UTF_8));}InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();return new String(readAll(in),StandardCharsets.UTF_8);}
 byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[4096];int n;while((n=in.read(x))!=-1)b.write(x,0,n);return b.toByteArray();}
 String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}String extract(String j,String k){String q="\""+k+"\":\"";int i=j.indexOf(q);if(i<0)return null;int e=j.indexOf('"',i+q.length());return e<0?null:j.substring(i+q.length(),e);}byte[] hexToBytes(String s){byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
}
